INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('d0de592d-b99b-4323-b26e-41a053d7b707', 'construction-products-family-by-family-d0de592d', 'en', 'Family by family: what the new Construction Products Regulation asks of Turkish building-material exporters', 'Regulation (EU) 2024/3110 has applied since 8 January 2026. It moves product families across one at a time and adds environmental data to the declaration.', 'Family by family', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-25', 'October 2026', 5, 15, 'Regulation (EU) 2024/3110 has applied since 8 January 2026. It moves product families across one at a time and adds environmental data to the declaration.', 'The new EU Construction Products Regulation, Regulation (EU) 2024/3110, entered into force on 7 January 2025 and its main provisions have applied since 8 January 2026. It replaces Regulation (EU) No 305/2011, but not overnight: each product family moves to the new rules when the Commission cites new harmonised technical specifications for it.', 'The new EU Construction Products Regulation, Regulation (EU) 2024/3110, entered into force on 7 January 2025 and its main provisions have applied since 8 January 2026. It replaces Regulation (EU) No 305/2011, but not overnight: each product family moves to the new rules when the Commission cites new harmonised technical specifications for it. For a Turkish exporter of ceramics, cement, glass, insulation, steel products or façade systems, the practical change is in the declaration. The declaration of performance and the declaration of conformity are combined, environmental characteristics based on life-cycle assessment are added step by step, and a digital product passport is planned to carry the information. The sound question is not whether the Regulation applies to us, but when each of our product families switches, what environmental data its technical specification will require, and whether we can produce that data without rebuilding our files twice.', '[{"title": "Family by family", "explanation": "The new EU Construction Products Regulation, Regulation (EU) 2024/3110, entered into force on 7 January 2025 and its main provisions have applied since 8 January 2026. It replaces Regulation (EU) No 305/2011, but not overnight: each product family moves to the new rules when the Commission cites new harmonised technical specifications for it.", "page": 2}, {"title": "Environmental data joins the declaration", "explanation": "For a Turkish exporter of ceramics, cement, glass, insulation, steel products or façade systems, the practical change is in the declaration. The declaration of performance and the declaration of conformity are combined, environmental characteristics based on life-cycle assessment are added step by step, and a digital product passport is planned to carry the information.", "page": 2}, {"title": "Sequence the work", "explanation": "The sound question is not whether the Regulation applies to us, but when each of our product families switches, what environmental data its technical specification will require, and whether we can produce that data without rebuilding our files twice.", "page": 2}]', '[]', '["Which of our product families are sold into the EU, and which harmonised standard covers each of them today?", "Has a new harmonised technical specification been cited, or is one expected, for any of them?", "Which EU customers already ask for environmental product declarations or embodied-carbon figures?", "Do we have plant-level data on energy, fuels, raw materials and yield that could support a life-cycle assessment?", "Who owns the declaration of performance today, and who will own the combined declaration?", "Which notified bodies do we rely on, and are they preparing for the new requirements?", "How will we supply information digitally when the product passport arrives?", "Which contracts and tender documents refer to the 2011 Regulation?"]', 'Desk review of official EU and Turkish sources checked on 24–25 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["Construction Products Regulation", "Building materials", "EU market access"]', '["Operating model"]', '["Construction Products Regulation", "CPR", "EPD", "embodied carbon", "digital product passport"]', 'fully_ungated', 'pdf-insights/d0de592d-b99b-4323-b26e-41a053d7b707/v1/Ganrich-Construction-Products-Regulation-EN.pdf', 'Ganrich-Construction-Products-Regulation-EN.pdf', '4b2f13721e25fdb31e82b44f0be42116cb724505b36e05fbc4551f968243c5ca', 'application/pdf', 262970, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', '2026-10-25T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000017', 'd0de592d-b99b-4323-b26e-41a053d7b707', 1, 'pdf-insights/d0de592d-b99b-4323-b26e-41a053d7b707/v1/Ganrich-Construction-Products-Regulation-EN.pdf', 'Ganrich-Construction-Products-Regulation-EN.pdf', '4b2f13721e25fdb31e82b44f0be42116cb724505b36e05fbc4551f968243c5ca', 262970, 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('22b37a1c-6746-4905-ae59-137973f106fc', 'espr-textiles-after-destruction-ban-22b37a1c', 'en', 'After the destruction ban: the ecodesign data EU fashion buyers will ask Turkish suppliers for', 'The Ecodesign for Sustainable Products Regulation already limits what brands can do with unsold clothes. Product rules and a digital passport for textiles come next.', 'After the destruction ban', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-25', 'October 2026', 5, 15, 'The Ecodesign for Sustainable Products Regulation already limits what brands can do with unsold clothes. Product rules and a digital passport for textiles come next.', 'Since 19 July 2026 large companies may no longer destroy unsold apparel, clothing accessories and footwear in the EU, under the Ecodesign for Sustainable Products Regulation, Regulation (EU) 2024/1781. Medium-sized companies follow on 19 July 2030. Companies that still discard unsold consumer products must publish what they discarded and why.', 'Since 19 July 2026 large companies may no longer destroy unsold apparel, clothing accessories and footwear in the EU, under the Ecodesign for Sustainable Products Regulation, Regulation (EU) 2024/1781. Medium-sized companies follow on 19 July 2030. Companies that still discard unsold consumer products must publish what they discarded and why. The Commission’s ESPR working plan schedules ecodesign requirements for textiles and apparel for 2027. They are expected to cover durability, recycled content and substances, and to bring a digital product passport that carries product data along the value chain. For a Turkish garment or textile supplier the effects arrive through the brand. Buyers who can no longer destroy overstock will order closer to demand and push for smaller, faster runs. Buyers who will need a product passport will ask for fibre, origin, processing and chemical data per model. The suppliers who can give that data cleanly will be easier to keep.', '[{"title": "The destruction ban is in force", "explanation": "Since 19 July 2026 large companies may no longer destroy unsold apparel, clothing accessories and footwear in the EU, under the Ecodesign for Sustainable Products Regulation, Regulation (EU) 2024/1781. Medium-sized companies follow on 19 July 2030. Companies that still discard unsold consumer products must publish what they discarded and why.", "page": 2}, {"title": "Order patterns change first", "explanation": "The Commission’s ESPR working plan schedules ecodesign requirements for textiles and apparel for 2027. They are expected to cover durability, recycled content and substances, and to bring a digital product passport that carries product data along the value chain.", "page": 2}, {"title": "Product data comes next", "explanation": "For a Turkish garment or textile supplier the effects arrive through the brand. Buyers who can no longer destroy overstock will order closer to demand and push for smaller, faster runs. Buyers who will need a product passport will ask for fibre, origin, processing and chemical data per model. The suppliers who can give that data cleanly will be easier to keep.", "page": 2}]', '[]', '["Which of our EU customers are large or medium-sized enterprises under the ESPR, and how are their ordering patterns changing?", "How much of our production is made against firm orders, and how much against forecasts that could leave unsold stock?", "Can we run smaller, faster replenishment cycles profitably?", "Do we hold fibre composition, recycled content and origin data at model level?", "Which processing steps are subcontracted, and do we know where each one happens?", "Where are our chemical test reports and durability results kept, and in what format?", "Which customers have already asked about product passports or ecodesign data?", "Would one data structure serve passport, forced labour and chemicals requests together?"]', 'Desk review of official EU and Turkish sources checked on 24–25 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["ESPR", "Textiles and apparel", "EU market access"]', '["Operating model"]', '["ESPR", "ecodesign", "destruction ban", "digital product passport", "textiles"]', 'fully_ungated', 'pdf-insights/22b37a1c-6746-4905-ae59-137973f106fc/v1/Ganrich-ESPR-Textiles-EN.pdf', 'Ganrich-ESPR-Textiles-EN.pdf', '39c33ea529adea0f3d6682d77b92991aab267ac98497284fd2af5ed5b2c03cb7', 'application/pdf', 263493, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', '2026-10-25T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000018', '22b37a1c-6746-4905-ae59-137973f106fc', 1, 'pdf-insights/22b37a1c-6746-4905-ae59-137973f106fc/v1/Ganrich-ESPR-Textiles-EN.pdf', 'Ganrich-ESPR-Textiles-EN.pdf', '39c33ea529adea0f3d6682d77b92991aab267ac98497284fd2af5ed5b2c03cb7', 263493, 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('ea4bc3b0-f4ac-4ec7-af97-056b40883326', 'nis2-supplier-security-evidence-ea4bc3b0', 'en', 'Your customer’s obligation, your evidence: NIS2 supply-chain security for Turkish suppliers', 'Most EU member states have now transposed the NIS2 Directive. Its supply-chain rules reach Turkish IT, software and industrial suppliers through contracts and questionnaires.', 'Your customer’s obligation, your evidence', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-25', 'October 2026', 5, 15, 'Most EU member states have now transposed the NIS2 Directive. Its supply-chain rules reach Turkish IT, software and industrial suppliers through contracts and questionnaires.', 'The NIS2 Directive, Directive (EU) 2022/2555, requires medium and large organisations in 18 sectors, from energy and transport to manufacturing of electronics, machinery and vehicles, to manage cybersecurity risk, including risk in their supply chain. The transposition deadline was 17 October 2024. Most member states missed it, but by spring 2026 a large majority had adopted national laws; Germany’s took effect on 6 December 2025.', 'The NIS2 Directive, Directive (EU) 2022/2555, requires medium and large organisations in 18 sectors, from energy and transport to manufacturing of electronics, machinery and vehicles, to manage cybersecurity risk, including risk in their supply chain. The transposition deadline was 17 October 2024. Most member states missed it, but by spring 2026 a large majority had adopted national laws; Germany’s took effect on 6 December 2025. Article 21 makes supply-chain security one of the minimum measures. EU entities must take into account the vulnerabilities of each direct supplier and the quality of their products and security practices. In practice they do this through questionnaires, contract clauses, audit rights and incident notification duties placed on suppliers. For a Turkish software house, managed service provider or supplier of connected industrial equipment, NIS2 is rarely a direct legal duty. It is a sales condition. The supplier that can show one credible security evidence pack, and commit to realistic incident notification, keeps the contract; the one that answers each questionnaire from scratch spends time and still looks risky.', '[{"title": "Most member states have transposed", "explanation": "The NIS2 Directive, Directive (EU) 2022/2555, requires medium and large organisations in 18 sectors, from energy and transport to manufacturing of electronics, machinery and vehicles, to manage cybersecurity risk, including risk in their supply chain. The transposition deadline was 17 October 2024. Most member states missed it, but by spring 2026 a large majority had adopted national laws; Germany’s took effect on 6 December 2025.", "page": 2}, {"title": "Supply chain is a minimum measure", "explanation": "Article 21 makes supply-chain security one of the minimum measures. EU entities must take into account the vulnerabilities of each direct supplier and the quality of their products and security practices. In practice they do this through questionnaires, contract clauses, audit rights and incident notification duties placed on suppliers.", "page": 2}, {"title": "Answer once, credibly", "explanation": "For a Turkish software house, managed service provider or supplier of connected industrial equipment, NIS2 is rarely a direct legal duty. It is a sales condition. The supplier that can show one credible security evidence pack, and commit to realistic incident notification, keeps the contract; the one that answers each questionnaire from scratch spends time and still looks risky.", "page": 2}]', '[]', '["Which of our EU customers are essential or important entities under NIS2, and in which countries?", "Have we received security questionnaires or new contract clauses in the past year, and how did we answer?", "Do we have a current, maintained set of security policies and evidence we could share?", "How quickly could we detect a security incident affecting a customer and notify them?", "Which of our own subcontractors and cloud providers could affect customer systems or data?", "How do we handle vulnerabilities in the software or devices we supply?", "Would ISO/IEC 27001 or another certification answer most customer questions for us?", "Who in leadership owns cybersecurity commitments made in contracts?"]', 'Desk review of official EU and Turkish sources checked on 24–25 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["NIS2", "Cybersecurity", "EU market access"]', '["Operating model"]', '["NIS2", "supply chain security", "ISO 27001", "incident reporting", "suppliers"]', 'fully_ungated', 'pdf-insights/ea4bc3b0-f4ac-4ec7-af97-056b40883326/v1/Ganrich-NIS2-Supplier-Security-EN.pdf', 'Ganrich-NIS2-Supplier-Security-EN.pdf', 'ef2d337368fb711627d06e5ce5657ee2ff0324671738cdbacc87d2c902ffa85c', 'application/pdf', 267339, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', '2026-10-25T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000019', 'ea4bc3b0-f4ac-4ec7-af97-056b40883326', 1, 'pdf-insights/ea4bc3b0-f4ac-4ec7-af97-056b40883326/v1/Ganrich-NIS2-Supplier-Security-EN.pdf', 'Ganrich-NIS2-Supplier-Security-EN.pdf', 'ef2d337368fb711627d06e5ce5657ee2ff0324671738cdbacc87d2c902ffa85c', 267339, 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('5c93bf77-e47b-4fe4-af73-60e779e502cb', 'eu-mdr-two-deadlines-database-5c93bf77', 'en', 'Two deadlines and a database: what EU MDR now asks of Turkish medical device manufacturers', 'Legacy certificates run out at the end of 2027 and 2028, and EUDAMED registration has been mandatory since 28 May 2026. A revision is on the table, but it does not move these dates.', 'Two deadlines and a database', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-25', 'October 2026', 5, 15, 'Legacy certificates run out at the end of 2027 and 2028, and EUDAMED registration has been mandatory since 28 May 2026. A revision is on the table, but it does not move these dates.', 'Under the EU Medical Device Regulation, Regulation (EU) 2017/745, devices still sold on certificates issued under the old directives can stay on the EU market only until 31 December 2027 for class III and implantable class IIb devices, and 31 December 2028 for other class IIb, class IIa and certain class I devices. Regulation (EU) 2023/607 granted these extensions on strict conditions, including an application to a notified body by 26 May 2024 and a signed agreement by 26 September 2024.', 'Under the EU Medical Device Regulation, Regulation (EU) 2017/745, devices still sold on certificates issued under the old directives can stay on the EU market only until 31 December 2027 for class III and implantable class IIb devices, and 31 December 2028 for other class IIb, class IIa and certain class I devices. Regulation (EU) 2023/607 granted these extensions on strict conditions, including an application to a notified body by 26 May 2024 and a signed agreement by 26 September 2024. Since 28 May 2026 four modules of the European database EUDAMED have been mandatory: actor registration, UDI and device registration, notified bodies and certificates, and market surveillance. Manufacturers must register devices and keep the data current, with transitional periods for devices already on the market. The Commission proposed a targeted revision of the MDR on 16 December 2025. It could ease certificate renewal and some documentation, but it was still in the legislative process in October 2026 and does not change the 2027 and 2028 deadlines. For a Turkish manufacturer the decision is portfolio triage: which devices to certify in time, which to redesign, and which to withdraw.', '[{"title": "Two legacy deadlines", "explanation": "Under the EU Medical Device Regulation, Regulation (EU) 2017/745, devices still sold on certificates issued under the old directives can stay on the EU market only until 31 December 2027 for class III and implantable class IIb devices, and 31 December 2028 for other class IIb, class IIa and certain class I devices. Regulation (EU) 2023/607 granted these extensions on strict conditions, including an application to a notified body by 26 May 2024 and a signed agreement by 26 September 2024.", "page": 2}, {"title": "EUDAMED is mandatory", "explanation": "Since 28 May 2026 four modules of the European database EUDAMED have been mandatory: actor registration, UDI and device registration, notified bodies and certificates, and market surveillance. Manufacturers must register devices and keep the data current, with transitional periods for devices already on the market.", "page": 2}, {"title": "Triage the portfolio", "explanation": "The Commission proposed a targeted revision of the MDR on 16 December 2025. It could ease certificate renewal and some documentation, but it was still in the legislative process in October 2026 and does not change the 2027 and 2028 deadlines. For a Turkish manufacturer the decision is portfolio triage: which devices to certify in time, which to redesign, and which to withdraw.", "page": 2}]', '[]', '["Which of our devices are still on the EU market under legacy certificates, and which deadline applies to each?", "Did each of them meet the 2024 application and agreement conditions?", "Where is each device in the notified body review, and what evidence is still missing?", "Which devices carry enough EU revenue to justify full MDR certification?", "Which variants could be consolidated, redesigned or withdrawn?", "Are our actor, UDI and device data in EUDAMED complete and consistent with our labels?", "Who notifies distributors and authorities if supply of a device will be interrupted?", "How would the proposed revision change our plans after 2028, if adopted?"]', 'Desk review of official EU and Turkish sources checked on 24–25 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["MDR", "Medical devices", "EU market access"]', '["Operating model"]', '["MDR", "EUDAMED", "legacy devices", "notified body", "medical devices"]', 'fully_ungated', 'pdf-insights/5c93bf77-e47b-4fe4-af73-60e779e502cb/v1/Ganrich-EU-MDR-Transition-EN.pdf', 'Ganrich-EU-MDR-Transition-EN.pdf', 'f0be4f84f71bfa5116b9f39f8284e0aa8246a17de7e892b32924e8ca541d26a8', 'application/pdf', 262387, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', '2026-10-25T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000020', '5c93bf77-e47b-4fe4-af73-60e779e502cb', 1, 'pdf-insights/5c93bf77-e47b-4fe4-af73-60e779e502cb/v1/Ganrich-EU-MDR-Transition-EN.pdf', 'Ganrich-EU-MDR-Transition-EN.pdf', 'f0be4f84f71bfa5116b9f39f8284e0aa8246a17de7e892b32924e8ca541d26a8', 262387, 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('97a36c53-d8d2-4ca2-b3e7-02beaa4ce0a9', 'supplier-sustainability-data-after-omnibus-97a36c53', 'en', 'Fewer reporters, sharper questions: sustainability data requests after the EU Omnibus', 'The EU narrowed who must report and capped what large companies can ask of smaller suppliers. For Turkish exporters, the requests do not stop; they become more standard.', 'Fewer reporters, sharper questions', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-25', 'October 2026', 5, 15, 'The EU narrowed who must report and capped what large companies can ask of smaller suppliers. For Turkish exporters, the requests do not stop; they become more standard.', 'The Omnibus I Directive, published in the Official Journal on 26 February 2026, cut the scope of the Corporate Sustainability Reporting Directive to EU companies with more than 1,000 employees and more than €450 million in turnover, and narrowed the due diligence directive to very large companies, with compliance from 26 July 2029.', 'The Omnibus I Directive, published in the Official Journal on 26 February 2026, cut the scope of the Corporate Sustainability Reporting Directive to EU companies with more than 1,000 employees and more than €450 million in turnover, and narrowed the due diligence directive to very large companies, with compliance from 26 July 2029. It also introduced a value-chain cap. Companies with fewer than 1,000 employees can decline requests for sustainability information that go beyond a voluntary standard. The Commission adopted that voluntary standard, based on EFRAG’s VSME, together with simplified reporting standards on 3 July 2026, and reporting companies must respect the cap from financial year 2027. For a Turkish supplier this changes the shape of the question, not its existence. The EU customers that still report will ask in a more standard format, and the largest buyers will keep asking because their own customers, lenders and product rules require it. A supplier that prepares one report along the voluntary standard can answer most requests with the same file.', '[{"title": "Fewer companies report", "explanation": "The Omnibus I Directive, published in the Official Journal on 26 February 2026, cut the scope of the Corporate Sustainability Reporting Directive to EU companies with more than 1,000 employees and more than €450 million in turnover, and narrowed the due diligence directive to very large companies, with compliance from 26 July 2029.", "page": 2}, {"title": "A cap on supplier requests", "explanation": "It also introduced a value-chain cap. Companies with fewer than 1,000 employees can decline requests for sustainability information that go beyond a voluntary standard. The Commission adopted that voluntary standard, based on EFRAG’s VSME, together with simplified reporting standards on 3 July 2026, and reporting companies must respect the cap from financial year 2027.", "page": 2}, {"title": "One base report answers most", "explanation": "For a Turkish supplier this changes the shape of the question, not its existence. The EU customers that still report will ask in a more standard format, and the largest buyers will keep asking because their own customers, lenders and product rules require it. A supplier that prepares one report along the voluntary standard can answer most requests with the same file.", "page": 2}]', '[]', '["Which of our EU customers remain in scope of the CSRD or the due diligence directive?", "How many sustainability questionnaires did we receive last year, and in how many formats?", "Could we prepare a report along the voluntary standard with the data we hold today?", "Are our energy, emissions and workforce figures consistent across reports, questionnaires and product filings?", "Do we report under TSRS, or will we cross its thresholds?", "Which customer requests relate to product rules such as CBAM or EUDR rather than general reporting?", "Who owns sustainability data across finance, operations and sales?", "Would a published report strengthen our position with EU buyers and lenders?"]', 'Desk review of official EU and Turkish sources checked on 24–25 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["CSRD", "Sustainability reporting", "EU market access"]', '["Operating model"]', '["Omnibus", "CSRD", "VSME", "value chain cap", "TSRS"]', 'fully_ungated', 'pdf-insights/97a36c53-d8d2-4ca2-b3e7-02beaa4ce0a9/v1/Ganrich-Supplier-Sustainability-Data-EN.pdf', 'Ganrich-Supplier-Sustainability-Data-EN.pdf', '44bd70be1dc03f742edd5f16d292b3e57009a2d5c6adeb1bb80678c9130f413d', 'application/pdf', 262711, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', '2026-10-25T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000021', '97a36c53-d8d2-4ca2-b3e7-02beaa4ce0a9', 1, 'pdf-insights/97a36c53-d8d2-4ca2-b3e7-02beaa4ce0a9/v1/Ganrich-Supplier-Sustainability-Data-EN.pdf', 'Ganrich-Supplier-Sustainability-Data-EN.pdf', '44bd70be1dc03f742edd5f16d292b3e57009a2d5c6adeb1bb80678c9130f413d', 262711, 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('69b43613-6779-4685-bb26-71fee5890644', 'yapi-urunleri-aile-aile-gecis-69b43613', 'tr', 'Aile aile geçiş: Yeni Yapı Ürünleri Tüzüğü Türk yapı malzemesi ihracatçılarından ne istiyor?', '(AB) 2024/3110 sayılı Tüzük 8 Ocak 2026’dan beri uygulanıyor. Ürün ailelerini birer birer yeni kurallara taşıyor ve beyana çevresel veri ekliyor.', 'Aile aile geçiş', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gül', '2026-10-25', 'Ekim 2026', 5, 15, '(AB) 2024/3110 sayılı Tüzük 8 Ocak 2026’dan beri uygulanıyor. Ürün ailelerini birer birer yeni kurallara taşıyor ve beyana çevresel veri ekliyor.', 'Yeni AB Yapı Ürünleri Tüzüğü, yani (AB) 2024/3110 sayılı Tüzük, 7 Ocak 2025’te yürürlüğe girdi; ana hükümleri 8 Ocak 2026’dan beri uygulanıyor. 305/2011 sayılı Tüzüğün yerini alıyor, ama bir gecede değil: Her ürün ailesi, Komisyon o aile için yeni uyumlaştırılmış teknik şartnameleri yayımladığında yeni kurallara geçiyor.', 'Yeni AB Yapı Ürünleri Tüzüğü, yani (AB) 2024/3110 sayılı Tüzük, 7 Ocak 2025’te yürürlüğe girdi; ana hükümleri 8 Ocak 2026’dan beri uygulanıyor. 305/2011 sayılı Tüzüğün yerini alıyor, ama bir gecede değil: Her ürün ailesi, Komisyon o aile için yeni uyumlaştırılmış teknik şartnameleri yayımladığında yeni kurallara geçiyor. Seramik, çimento, cam, yalıtım, çelik ürünleri veya cephe sistemleri ihraç eden bir Türk firması için pratikteki değişiklik beyanda. Performans beyanı ile uygunluk beyanı birleşiyor, yaşam döngüsü değerlendirmesine dayalı çevresel özellikler adım adım ekleniyor ve bu bilgiyi taşıyacak bir dijital ürün pasaportu planlanıyor. Doğru soru Tüzüğün bize uygulanıp uygulanmadığı değil; ürün ailelerimizin her birinin ne zaman geçeceği, teknik şartnamesinin hangi çevresel veriyi isteyeceği ve bu veriyi dosyalarımızı iki kez yeniden kurmadan üretip üretemeyeceğimizdir.', '[{"title": "Aile aile geçiş", "explanation": "Yeni AB Yapı Ürünleri Tüzüğü, yani (AB) 2024/3110 sayılı Tüzük, 7 Ocak 2025’te yürürlüğe girdi; ana hükümleri 8 Ocak 2026’dan beri uygulanıyor. 305/2011 sayılı Tüzüğün yerini alıyor, ama bir gecede değil: Her ürün ailesi, Komisyon o aile için yeni uyumlaştırılmış teknik şartnameleri yayımladığında yeni kurallara geçiyor.", "page": 2}, {"title": "Çevresel veri beyana giriyor", "explanation": "Seramik, çimento, cam, yalıtım, çelik ürünleri veya cephe sistemleri ihraç eden bir Türk firması için pratikteki değişiklik beyanda. Performans beyanı ile uygunluk beyanı birleşiyor, yaşam döngüsü değerlendirmesine dayalı çevresel özellikler adım adım ekleniyor ve bu bilgiyi taşıyacak bir dijital ürün pasaportu planlanıyor.", "page": 2}, {"title": "İşi sıraya koyun", "explanation": "Doğru soru Tüzüğün bize uygulanıp uygulanmadığı değil; ürün ailelerimizin her birinin ne zaman geçeceği, teknik şartnamesinin hangi çevresel veriyi isteyeceği ve bu veriyi dosyalarımızı iki kez yeniden kurmadan üretip üretemeyeceğimizdir.", "page": 2}]', '[]', '["Hangi ürün ailelerimiz AB’ye satılıyor ve her birini bugün hangi uyumlaştırılmış standart kapsıyor?", "Bunlardan herhangi biri için yeni bir uyumlaştırılmış teknik şartname yayımlandı mı ya da bekleniyor mu?", "Hangi AB müşterilerimiz şimdiden çevresel ürün beyanı veya gömülü karbon değeri istiyor?", "Yaşam döngüsü değerlendirmesini destekleyecek tesis bazında enerji, yakıt, hammadde ve verim verimiz var mı?", "Performans beyanının bugün sahibi kim, birleşik beyanın sahibi kim olacak?", "Hangi onaylanmış kuruluşlarla çalışıyoruz ve yeni gerekliliklere hazırlanıyorlar mı?", "Ürün pasaportu geldiğinde bilgiyi dijital olarak nasıl sağlayacağız?", "Hangi sözleşme ve ihale belgeleri 2011 Tüzüğüne atıf yapıyor?"]', '24–25 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["Construction Products Regulation", "Building materials", "EU market access"]', '["Operating model"]', '["Construction Products Regulation", "CPR", "EPD", "embodied carbon", "digital product passport"]', 'fully_ungated', 'pdf-insights/69b43613-6779-4685-bb26-71fee5890644/v1/Ganrich-Yapi-Urunleri-Tuzugu-TR.pdf', 'Ganrich-Yapi-Urunleri-Tuzugu-TR.pdf', '51a546607c2d8a6e89ebdc403fca952db66a191ae22034b605be84810b40a5a2', 'application/pdf', 273115, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', '2026-10-25T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000022', '69b43613-6779-4685-bb26-71fee5890644', 1, 'pdf-insights/69b43613-6779-4685-bb26-71fee5890644/v1/Ganrich-Yapi-Urunleri-Tuzugu-TR.pdf', 'Ganrich-Yapi-Urunleri-Tuzugu-TR.pdf', '51a546607c2d8a6e89ebdc403fca952db66a191ae22034b605be84810b40a5a2', 273115, 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('9b18a3aa-85b7-4fde-96c7-5300626f4154', 'espr-tekstil-imha-yasagindan-sonra-9b18a3aa', 'tr', 'İmha yasağından sonra: AB moda alıcılarının Türk tedarikçilerden isteyeceği ekotasarım verisi', 'Sürdürülebilir Ürünler için Ekotasarım Tüzüğü, markaların satılmayan kıyafetlerle ne yapabileceğini şimdiden sınırlıyor. Sırada tekstil için ürün kuralları ve dijital pasaport var.', 'İmha yasağından sonra', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gül', '2026-10-25', 'Ekim 2026', 5, 15, 'Sürdürülebilir Ürünler için Ekotasarım Tüzüğü, markaların satılmayan kıyafetlerle ne yapabileceğini şimdiden sınırlıyor. Sırada tekstil için ürün kuralları ve dijital pasaport var.', '(AB) 2024/1781 sayılı Sürdürülebilir Ürünler için Ekotasarım Tüzüğü uyarınca, büyük şirketler 19 Temmuz 2026’dan beri AB’de satılmayan giyim, giyim aksesuarı ve ayakkabıyı imha edemiyor. Orta ölçekli şirketler 19 Temmuz 2030’da bu kapsama giriyor. Satılmayan tüketici ürünlerini hâlâ elden çıkaran şirketler, neyi ve neden elden çıkardıklarını yayımlamak zorunda.', '(AB) 2024/1781 sayılı Sürdürülebilir Ürünler için Ekotasarım Tüzüğü uyarınca, büyük şirketler 19 Temmuz 2026’dan beri AB’de satılmayan giyim, giyim aksesuarı ve ayakkabıyı imha edemiyor. Orta ölçekli şirketler 19 Temmuz 2030’da bu kapsama giriyor. Satılmayan tüketici ürünlerini hâlâ elden çıkaran şirketler, neyi ve neden elden çıkardıklarını yayımlamak zorunda. Komisyonun ESPR çalışma planı, tekstil ve hazır giyim için ekotasarım gerekliliklerini 2027’ye planlıyor. Bu kuralların dayanıklılık, geri dönüştürülmüş içerik ve maddeleri kapsaması ve ürün verisini değer zinciri boyunca taşıyan bir dijital ürün pasaportu getirmesi bekleniyor. Türk hazır giyim veya tekstil tedarikçisi için etkiler markalar üzerinden geliyor. Fazla stoku artık imha edemeyen alıcılar talebe daha yakın sipariş verecek; daha küçük ve hızlı üretim partileri isteyecek. Ürün pasaportuna ihtiyaç duyacak alıcılar model bazında elyaf, menşe, işlem ve kimyasal verisi isteyecek. Bu veriyi düzenli biçimde verebilen tedarikçiyi elde tutmak daha kolay olacak.', '[{"title": "İmha yasağı yürürlükte", "explanation": "(AB) 2024/1781 sayılı Sürdürülebilir Ürünler için Ekotasarım Tüzüğü uyarınca, büyük şirketler 19 Temmuz 2026’dan beri AB’de satılmayan giyim, giyim aksesuarı ve ayakkabıyı imha edemiyor. Orta ölçekli şirketler 19 Temmuz 2030’da bu kapsama giriyor. Satılmayan tüketici ürünlerini hâlâ elden çıkaran şirketler, neyi ve neden elden çıkardıklarını yayımlamak zorunda.", "page": 2}, {"title": "Önce sipariş düzeni değişiyor", "explanation": "Komisyonun ESPR çalışma planı, tekstil ve hazır giyim için ekotasarım gerekliliklerini 2027’ye planlıyor. Bu kuralların dayanıklılık, geri dönüştürülmüş içerik ve maddeleri kapsaması ve ürün verisini değer zinciri boyunca taşıyan bir dijital ürün pasaportu getirmesi bekleniyor.", "page": 2}, {"title": "Sırada ürün verisi var", "explanation": "Türk hazır giyim veya tekstil tedarikçisi için etkiler markalar üzerinden geliyor. Fazla stoku artık imha edemeyen alıcılar talebe daha yakın sipariş verecek; daha küçük ve hızlı üretim partileri isteyecek. Ürün pasaportuna ihtiyaç duyacak alıcılar model bazında elyaf, menşe, işlem ve kimyasal verisi isteyecek. Bu veriyi düzenli biçimde verebilen tedarikçiyi elde tutmak daha kolay olacak.", "page": 2}]', '[]', '["AB müşterilerimizden hangileri ESPR kapsamında büyük veya orta ölçekli işletme ve sipariş düzenleri nasıl değişiyor?", "Üretimimizin ne kadarı kesin siparişe, ne kadarı satılmayan stok bırakabilecek tahminlere göre yapılıyor?", "Daha küçük ve hızlı yenileme döngülerini kârlı biçimde çalıştırabilir miyiz?", "Elyaf bileşimi, geri dönüştürülmüş içerik ve menşe verisini model bazında tutuyor muyuz?", "Hangi işlem adımları fasona veriliyor ve her birinin nerede yapıldığını biliyor muyuz?", "Kimyasal test raporlarımız ve dayanıklılık sonuçlarımız nerede ve hangi biçimde tutuluyor?", "Hangi müşteriler ürün pasaportunu veya ekotasarım verisini şimdiden sordu?", "Tek bir veri yapısı pasaport, zorla çalıştırma ve kimyasal taleplerine birlikte hizmet edebilir mi?"]', '24–25 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["ESPR", "Textiles and apparel", "EU market access"]', '["Operating model"]', '["ESPR", "ecodesign", "destruction ban", "digital product passport", "textiles"]', 'fully_ungated', 'pdf-insights/9b18a3aa-85b7-4fde-96c7-5300626f4154/v1/Ganrich-ESPR-Tekstil-TR.pdf', 'Ganrich-ESPR-Tekstil-TR.pdf', '3f555bfa287d1f36b97c39f527e56d3202c704650ac82b524496dbd618e9399a', 'application/pdf', 276476, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', '2026-10-25T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000023', '9b18a3aa-85b7-4fde-96c7-5300626f4154', 1, 'pdf-insights/9b18a3aa-85b7-4fde-96c7-5300626f4154/v1/Ganrich-ESPR-Tekstil-TR.pdf', 'Ganrich-ESPR-Tekstil-TR.pdf', '3f555bfa287d1f36b97c39f527e56d3202c704650ac82b524496dbd618e9399a', 276476, 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('afa3e63f-e005-45c6-af6a-504bf53c78b7', 'nis2-tedarikci-guvenligi-kaniti-afa3e63f', 'tr', 'Müşterinin yükümlülüğü, sizin kanıtınız: Türk tedarikçiler için NIS2 tedarik zinciri güvenliği', 'AB üye devletlerinin çoğu NIS2 Direktifini artık iç hukuka aktardı. Tedarik zinciri kuralları, Türk BT, yazılım ve sanayi tedarikçilerine sözleşmeler ve anketler yoluyla ulaşıyor.', 'Müşterinin yükümlülüğü, sizin kanıtınız', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gül', '2026-10-25', 'Ekim 2026', 5, 15, 'AB üye devletlerinin çoğu NIS2 Direktifini artık iç hukuka aktardı. Tedarik zinciri kuralları, Türk BT, yazılım ve sanayi tedarikçilerine sözleşmeler ve anketler yoluyla ulaşıyor.', '(AB) 2022/2555 sayılı NIS2 Direktifi; enerji ve ulaştırmadan elektronik, makine ve motorlu araç üretimine kadar 18 sektördeki orta ve büyük kuruluşların siber güvenlik riskini, tedarik zincirindeki risk dahil, yönetmesini istiyor. İç hukuka aktarma için son tarih 17 Ekim 2024’tü. Üye devletlerin çoğu bu tarihi kaçırdı; ama 2026 baharında büyük çoğunluğu ulusal yasalarını kabul etmişti. Almanya’nın yasası 6 Aralık 2025’te yürürlüğe girdi.', '(AB) 2022/2555 sayılı NIS2 Direktifi; enerji ve ulaştırmadan elektronik, makine ve motorlu araç üretimine kadar 18 sektördeki orta ve büyük kuruluşların siber güvenlik riskini, tedarik zincirindeki risk dahil, yönetmesini istiyor. İç hukuka aktarma için son tarih 17 Ekim 2024’tü. Üye devletlerin çoğu bu tarihi kaçırdı; ama 2026 baharında büyük çoğunluğu ulusal yasalarını kabul etmişti. Almanya’nın yasası 6 Aralık 2025’te yürürlüğe girdi. 21. Madde, tedarik zinciri güvenliğini asgari önlemlerden biri yapıyor. AB’deki kuruluşlar her doğrudan tedarikçinin zafiyetlerini ve ürünlerinin ve güvenlik uygulamalarının kalitesini dikkate almak zorunda. Pratikte bunu anketler, sözleşme maddeleri, denetim hakları ve tedarikçilere yüklenen olay bildirim yükümlülükleriyle yapıyorlar. Türk yazılım firması, yönetilen hizmet sağlayıcısı veya bağlantılı sanayi ekipmanı tedarikçisi için NIS2 nadiren doğrudan bir hukuki yükümlülük. Bir satış koşulu. Tek ve inandırıcı bir güvenlik kanıt paketi gösterebilen ve gerçekçi bir olay bildirimi taahhüdü veren tedarikçi sözleşmeyi koruyor; her anketi sıfırdan yanıtlayan ise zaman harcıyor ve yine de riskli görünüyor.', '[{"title": "Üye devletlerin çoğu iç hukuka aktardı", "explanation": "(AB) 2022/2555 sayılı NIS2 Direktifi; enerji ve ulaştırmadan elektronik, makine ve motorlu araç üretimine kadar 18 sektördeki orta ve büyük kuruluşların siber güvenlik riskini, tedarik zincirindeki risk dahil, yönetmesini istiyor. İç hukuka aktarma için son tarih 17 Ekim 2024’tü. Üye devletlerin çoğu bu tarihi kaçırdı; ama 2026 baharında büyük çoğunluğu ulusal yasalarını kabul etmişti. Almanya’nın yasası 6 Aralık 2025’te yürürlüğe girdi.", "page": 2}, {"title": "Tedarik zinciri asgari önlem", "explanation": "21. Madde, tedarik zinciri güvenliğini asgari önlemlerden biri yapıyor. AB’deki kuruluşlar her doğrudan tedarikçinin zafiyetlerini ve ürünlerinin ve güvenlik uygulamalarının kalitesini dikkate almak zorunda. Pratikte bunu anketler, sözleşme maddeleri, denetim hakları ve tedarikçilere yüklenen olay bildirim yükümlülükleriyle yapıyorlar.", "page": 2}, {"title": "Bir kez ve inandırıcı yanıt", "explanation": "Türk yazılım firması, yönetilen hizmet sağlayıcısı veya bağlantılı sanayi ekipmanı tedarikçisi için NIS2 nadiren doğrudan bir hukuki yükümlülük. Bir satış koşulu. Tek ve inandırıcı bir güvenlik kanıt paketi gösterebilen ve gerçekçi bir olay bildirimi taahhüdü veren tedarikçi sözleşmeyi koruyor; her anketi sıfırdan yanıtlayan ise zaman harcıyor ve yine de riskli görünüyor.", "page": 2}]', '[]', '["AB müşterilerimizden hangileri NIS2 kapsamında temel veya önemli kuruluş ve hangi ülkelerde?", "Son bir yılda güvenlik anketi veya yeni sözleşme maddesi aldık mı, nasıl yanıtladık?", "Paylaşabileceğimiz güncel ve bakımı yapılan bir güvenlik politikaları ve kanıt setimiz var mı?", "Bir müşteriyi etkileyen güvenlik olayını ne kadar hızlı fark edip bildirebiliriz?", "Kendi alt yüklenicilerimizden ve bulut sağlayıcılarımızdan hangileri müşteri sistemlerini veya verisini etkileyebilir?", "Sağladığımız yazılım veya cihazlardaki zafiyetleri nasıl yönetiyoruz?", "ISO/IEC 27001 veya başka bir belgelendirme, müşteri sorularının çoğunu bizim için yanıtlar mı?", "Sözleşmelerde verilen siber güvenlik taahhütlerinin yönetimdeki sahibi kim?"]', '24–25 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["NIS2", "Cybersecurity", "EU market access"]', '["Operating model"]', '["NIS2", "supply chain security", "ISO 27001", "incident reporting", "suppliers"]', 'fully_ungated', 'pdf-insights/afa3e63f-e005-45c6-af6a-504bf53c78b7/v1/Ganrich-NIS2-Tedarikci-Guvenligi-TR.pdf', 'Ganrich-NIS2-Tedarikci-Guvenligi-TR.pdf', '72f039bdf10552e137cca772b6522351b3df07d1cac75049d30ffd41c0882176', 'application/pdf', 275774, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', '2026-10-25T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000024', 'afa3e63f-e005-45c6-af6a-504bf53c78b7', 1, 'pdf-insights/afa3e63f-e005-45c6-af6a-504bf53c78b7/v1/Ganrich-NIS2-Tedarikci-Guvenligi-TR.pdf', 'Ganrich-NIS2-Tedarikci-Guvenligi-TR.pdf', '72f039bdf10552e137cca772b6522351b3df07d1cac75049d30ffd41c0882176', 275774, 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('9abc973b-91f7-4484-a73f-8c52dcb4d0e4', 'ab-mdr-iki-son-tarih-9abc973b', 'tr', 'İki son tarih ve bir veri tabanı: AB MDR Türk tıbbi cihaz üreticilerinden artık ne istiyor?', 'Eski sertifikalar 2027 ve 2028 sonunda bitiyor; EUDAMED kaydı 28 Mayıs 2026’dan beri zorunlu. Masada bir revizyon var, ama bu tarihleri değiştirmiyor.', 'İki son tarih ve bir veri tabanı', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gül', '2026-10-25', 'Ekim 2026', 5, 15, 'Eski sertifikalar 2027 ve 2028 sonunda bitiyor; EUDAMED kaydı 28 Mayıs 2026’dan beri zorunlu. Masada bir revizyon var, ama bu tarihleri değiştirmiyor.', '(AB) 2017/745 sayılı AB Tıbbi Cihaz Tüzüğü uyarınca, eski direktifler kapsamında verilmiş sertifikalarla satılmaya devam eden cihazlar AB pazarında ancak sınıf III ve implante edilebilir sınıf IIb cihazlar için 31 Aralık 2027’ye, diğer sınıf IIb, sınıf IIa ve bazı sınıf I cihazlar için 31 Aralık 2028’e kadar kalabiliyor. (AB) 2023/607 sayılı Tüzük bu uzatmaları sıkı koşullara bağladı; bunlar arasında 26 Mayıs 2024’e kadar onaylanmış kuruluşa başvuru ve 26 Eylül 2024’e kadar imzalı sözleşme var.', '(AB) 2017/745 sayılı AB Tıbbi Cihaz Tüzüğü uyarınca, eski direktifler kapsamında verilmiş sertifikalarla satılmaya devam eden cihazlar AB pazarında ancak sınıf III ve implante edilebilir sınıf IIb cihazlar için 31 Aralık 2027’ye, diğer sınıf IIb, sınıf IIa ve bazı sınıf I cihazlar için 31 Aralık 2028’e kadar kalabiliyor. (AB) 2023/607 sayılı Tüzük bu uzatmaları sıkı koşullara bağladı; bunlar arasında 26 Mayıs 2024’e kadar onaylanmış kuruluşa başvuru ve 26 Eylül 2024’e kadar imzalı sözleşme var. 28 Mayıs 2026’dan beri Avrupa veri tabanı EUDAMED’in dört modülü zorunlu: aktör kaydı, UDI ve cihaz kaydı, onaylanmış kuruluşlar ve sertifikalar, piyasa gözetimi. Üreticiler cihazlarını kaydetmeli ve veriyi güncel tutmalı; piyasadaki cihazlar için geçiş süreleri var. Komisyon 16 Aralık 2025’te MDR için hedefli bir revizyon önerdi. Sertifika yenilemeyi ve bazı dokümantasyonu kolaylaştırabilir; ama Ekim 2026’da hâlâ yasama sürecindeydi ve 2027 ile 2028 son tarihlerini değiştirmiyor. Türk üretici için karar bir portföy önceliklendirmesi: hangi cihazlar zamanında belgelendirilecek, hangileri yeniden tasarlanacak, hangileri geri çekilecek.', '[{"title": "İki son tarih", "explanation": "(AB) 2017/745 sayılı AB Tıbbi Cihaz Tüzüğü uyarınca, eski direktifler kapsamında verilmiş sertifikalarla satılmaya devam eden cihazlar AB pazarında ancak sınıf III ve implante edilebilir sınıf IIb cihazlar için 31 Aralık 2027’ye, diğer sınıf IIb, sınıf IIa ve bazı sınıf I cihazlar için 31 Aralık 2028’e kadar kalabiliyor. (AB) 2023/607 sayılı Tüzük bu uzatmaları sıkı koşullara bağladı; bunlar arasında 26 Mayıs 2024’e kadar onaylanmış kuruluşa başvuru ve 26 Eylül 2024’e kadar imzalı sözleşme var.", "page": 2}, {"title": "EUDAMED zorunlu", "explanation": "28 Mayıs 2026’dan beri Avrupa veri tabanı EUDAMED’in dört modülü zorunlu: aktör kaydı, UDI ve cihaz kaydı, onaylanmış kuruluşlar ve sertifikalar, piyasa gözetimi. Üreticiler cihazlarını kaydetmeli ve veriyi güncel tutmalı; piyasadaki cihazlar için geçiş süreleri var.", "page": 2}, {"title": "Portföyü önceliklendirin", "explanation": "Komisyon 16 Aralık 2025’te MDR için hedefli bir revizyon önerdi. Sertifika yenilemeyi ve bazı dokümantasyonu kolaylaştırabilir; ama Ekim 2026’da hâlâ yasama sürecindeydi ve 2027 ile 2028 son tarihlerini değiştirmiyor. Türk üretici için karar bir portföy önceliklendirmesi: hangi cihazlar zamanında belgelendirilecek, hangileri yeniden tasarlanacak, hangileri geri çekilecek.", "page": 2}]', '[]', '["Hangi cihazlarımız AB pazarında hâlâ eski sertifikalarla bulunuyor ve her birine hangi son tarih uygulanıyor?", "Her biri 2024 başvuru ve sözleşme koşullarını karşıladı mı?", "Her cihaz onaylanmış kuruluş incelemesinin neresinde ve hangi kanıtlar hâlâ eksik?", "Hangi cihazlar tam MDR belgelendirmesini haklı kılacak kadar AB geliri taşıyor?", "Hangi varyantlar birleştirilebilir, yeniden tasarlanabilir veya geri çekilebilir?", "EUDAMED’deki aktör, UDI ve cihaz verimiz eksiksiz ve etiketlerimizle tutarlı mı?", "Bir cihazın tedariki kesintiye uğrayacaksa distribütörleri ve makamları kim bilgilendiriyor?", "Önerilen revizyon kabul edilirse 2028 sonrası planlarımızı nasıl değiştirir?"]', '24–25 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["MDR", "Medical devices", "EU market access"]', '["Operating model"]', '["MDR", "EUDAMED", "legacy devices", "notified body", "medical devices"]', 'fully_ungated', 'pdf-insights/9abc973b-91f7-4484-a73f-8c52dcb4d0e4/v1/Ganrich-AB-MDR-Gecisi-TR.pdf', 'Ganrich-AB-MDR-Gecisi-TR.pdf', '3e4d716a0ef389fb952de8a793aa90d3aa3b740ffaa9a81a7be4bf7817039eba', 'application/pdf', 274908, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', '2026-10-25T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000025', '9abc973b-91f7-4484-a73f-8c52dcb4d0e4', 1, 'pdf-insights/9abc973b-91f7-4484-a73f-8c52dcb4d0e4/v1/Ganrich-AB-MDR-Gecisi-TR.pdf', 'Ganrich-AB-MDR-Gecisi-TR.pdf', '3e4d716a0ef389fb952de8a793aa90d3aa3b740ffaa9a81a7be4bf7817039eba', 274908, 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('82382d59-7cbe-40ab-b00a-68eaf6d866b1', 'tedarikci-surdurulebilirlik-verisi-omnibus-82382d59', 'tr', 'Daha az raporlayan, daha net sorular: AB Omnibus sonrasında sürdürülebilirlik veri talepleri', 'AB, kimin raporlayacağını daralttı ve büyük şirketlerin küçük tedarikçilerden isteyebileceklerine sınır koydu. Türk ihracatçılar için talepler bitmiyor; daha standart hale geliyor.', 'Daha az raporlayan, daha net sorular', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gül', '2026-10-25', 'Ekim 2026', 5, 15, 'AB, kimin raporlayacağını daralttı ve büyük şirketlerin küçük tedarikçilerden isteyebileceklerine sınır koydu. Türk ihracatçılar için talepler bitmiyor; daha standart hale geliyor.', '26 Şubat 2026’da AB Resmî Gazetesi’nde yayımlanan Omnibus I Direktifi, Kurumsal Sürdürülebilirlik Raporlaması Direktifinin kapsamını 1.000’den fazla çalışanı ve 450 milyon €’dan fazla cirosu olan AB şirketleriyle sınırladı; durum tespiti direktifini de çok büyük şirketlere daralttı ve uyum tarihini 26 Temmuz 2029 yaptı.', '26 Şubat 2026’da AB Resmî Gazetesi’nde yayımlanan Omnibus I Direktifi, Kurumsal Sürdürülebilirlik Raporlaması Direktifinin kapsamını 1.000’den fazla çalışanı ve 450 milyon €’dan fazla cirosu olan AB şirketleriyle sınırladı; durum tespiti direktifini de çok büyük şirketlere daralttı ve uyum tarihini 26 Temmuz 2029 yaptı. Ayrıca bir değer zinciri sınırı getirdi. 1.000’den az çalışanı olan şirketler, gönüllü bir standardı aşan sürdürülebilirlik bilgisi taleplerini reddedebiliyor. Komisyon, EFRAG’ın VSME standardına dayanan bu gönüllü standardı sadeleştirilmiş raporlama standartlarıyla birlikte 3 Temmuz 2026’da kabul etti; raporlayan şirketler bu sınıra 2027 mali yılından itibaren uymak zorunda. Türk tedarikçi için bu, sorunun varlığını değil biçimini değiştiriyor. Raporlamaya devam eden AB müşterileri daha standart bir biçimde soracak; en büyük alıcılar ise kendi müşterileri, finansörleri ve ürün kuralları gerektirdiği için sormaya devam edecek. Gönüllü standarda göre tek bir rapor hazırlayan tedarikçi, taleplerin çoğunu aynı dosyayla yanıtlayabilir.', '[{"title": "Daha az şirket raporluyor", "explanation": "26 Şubat 2026’da AB Resmî Gazetesi’nde yayımlanan Omnibus I Direktifi, Kurumsal Sürdürülebilirlik Raporlaması Direktifinin kapsamını 1.000’den fazla çalışanı ve 450 milyon €’dan fazla cirosu olan AB şirketleriyle sınırladı; durum tespiti direktifini de çok büyük şirketlere daralttı ve uyum tarihini 26 Temmuz 2029 yaptı.", "page": 2}, {"title": "Tedarikçi taleplerine sınır", "explanation": "Ayrıca bir değer zinciri sınırı getirdi. 1.000’den az çalışanı olan şirketler, gönüllü bir standardı aşan sürdürülebilirlik bilgisi taleplerini reddedebiliyor. Komisyon, EFRAG’ın VSME standardına dayanan bu gönüllü standardı sadeleştirilmiş raporlama standartlarıyla birlikte 3 Temmuz 2026’da kabul etti; raporlayan şirketler bu sınıra 2027 mali yılından itibaren uymak zorunda.", "page": 2}, {"title": "Tek temel rapor çoğunu yanıtlar", "explanation": "Türk tedarikçi için bu, sorunun varlığını değil biçimini değiştiriyor. Raporlamaya devam eden AB müşterileri daha standart bir biçimde soracak; en büyük alıcılar ise kendi müşterileri, finansörleri ve ürün kuralları gerektirdiği için sormaya devam edecek. Gönüllü standarda göre tek bir rapor hazırlayan tedarikçi, taleplerin çoğunu aynı dosyayla yanıtlayabilir.", "page": 2}]', '[]', '["AB müşterilerimizden hangileri CSRD veya durum tespiti direktifi kapsamında kalıyor?", "Geçen yıl kaç sürdürülebilirlik anketi aldık ve kaç farklı biçimde?", "Bugün elimizdeki veriyle gönüllü standarda göre bir rapor hazırlayabilir miyiz?", "Enerji, emisyon ve işgücü rakamlarımız raporlarda, anketlerde ve ürün başvurularında tutarlı mı?", "TSRS’ye göre raporluyor muyuz, ya da eşiklerini aşacak mıyız?", "Hangi müşteri talepleri genel raporlamayla değil, CBAM veya EUDR gibi ürün kurallarıyla ilgili?", "Finans, operasyon ve satış arasında sürdürülebilirlik verisinin sahibi kim?", "Yayımlanmış bir rapor AB alıcıları ve finansörler nezdinde konumumuzu güçlendirir mi?"]', '24–25 Ekim 2026’da kontrol edilen resmî AB ve Türkiye kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["CSRD", "Sustainability reporting", "EU market access"]', '["Operating model"]', '["Omnibus", "CSRD", "VSME", "value chain cap", "TSRS"]', 'fully_ungated', 'pdf-insights/82382d59-7cbe-40ab-b00a-68eaf6d866b1/v1/Ganrich-Tedarikci-Surdurulebilirlik-Verisi-TR.pdf', 'Ganrich-Tedarikci-Surdurulebilirlik-Verisi-TR.pdf', '1ce35432c690aa6356eb88ce81b6592a8dfbd9bdefa4462ab5b573b70653699a', 'application/pdf', 273833, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', '2026-10-25T09:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000026', '82382d59-7cbe-40ab-b00a-68eaf6d866b1', 1, 'pdf-insights/82382d59-7cbe-40ab-b00a-68eaf6d866b1/v1/Ganrich-Tedarikci-Surdurulebilirlik-Verisi-TR.pdf', 'Ganrich-Tedarikci-Surdurulebilirlik-Verisi-TR.pdf', '1ce35432c690aa6356eb88ce81b6592a8dfbd9bdefa4462ab5b573b70653699a', 273833, 'furkangul@ganrichadvisory.com', '2026-10-25T09:00:00.000Z', 'current');
